package org.example.erp.modules.accounting.application.events;

import org.example.erp.modules.accounting.application.dto.JournalEntryDTO;
import org.example.erp.platform.BaseIntegrationEvent;

import java.util.LinkedHashMap;
import java.util.Map;

/** Any posted entry, manual or generated by another workflow; origin tells which. */
public final class JournalEntryPosted extends BaseIntegrationEvent {
    private final JournalEntryDTO entry;

    public JournalEntryPosted(JournalEntryDTO entry) {
        super(entry.reference(), null);
        this.entry = entry;
    }

    public JournalEntryDTO entry() {
        return entry;
    }

    @Override
    public String eventName() {
        return "accounting.journal-entry-posted";
    }

    @Override
    public Map<String, Object> payload() {
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("entryId", entry.id());
        payload.put("reference", entry.reference());
        payload.put("entryDate", entry.entryDate().toString());
        payload.put("origin", entry.origin().name());
        payload.put("description", entry.description());
        payload.put("total", entry.total().toPlainString());
        payload.put("reversalOf", entry.reversalOf());
        return payload;
    }
}
